582	static lv_obj_t *settings_row_switch(lv_obj_t *card, const char *icon,
583	                                      uint32_t icon_color, const char *label,
584	                                      bool initial_state)
585	{
586	    lv_obj_t *row = make_clean_cont(card);
587	    lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);
588	    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
589	    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
590	                          LV_FLEX_ALIGN_CENTER);
591	    lv_obj_set_style_pad_column(row, 12, 0);
592	
593	    /* Icon badge */
594	    lv_obj_t *badge = lv_obj_create(row);
595	    lv_obj_set_size(badge, DM(36), DM(36));
596	    lv_obj_set_style_radius(badge, RAD_CARD, 0);
597	    lv_obj_set_style_bg_color(badge, lv_color_hex(icon_color), 0);
598	    lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
599	    /* Colored glow — echoes Music cover / Games badge */
600	    lv_obj_set_style_shadow_width(badge, 8, 0);
601	    lv_obj_set_style_shadow_color(badge, lv_color_hex(icon_color), 0);
602	    lv_obj_set_style_shadow_opa(badge, LV_OPA_30, 0);
603	    lv_obj_set_style_border_width(badge, 0, 0);
604	    lv_obj_set_style_pad_all(badge, 0, 0);
605	    lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
606	    lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);
607	
608	    lv_obj_t *ic = lv_label_create(badge);
609	    lv_label_set_text(ic, icon);
610	    lv_obj_set_style_text_font(ic, FONT_ICON, 0);
611	    lv_obj_set_style_text_color(ic, lv_color_hex(0xFFFFFF), 0);
612	    lv_obj_center(ic);
613	
614	    /* Label */
615	    lv_obj_t *lb = lv_label_create(row);
616	    lv_label_set_text(lb, label);
617	    lv_obj_set_style_text_font(lb, FONT_BODY, 0);
618	    lv_obj_set_style_text_color(lb, lv_color_hex(COL_TEXT), 0);
619	    lv_obj_set_flex_grow(lb, 1);
620	
621	    /* Switch */
622	    lv_obj_t *sw = lv_switch_create(row);
623	    lv_obj_set_size(sw, DM(44), DM(24));
624	    if (initial_state)
625	        lv_obj_add_state(sw, LV_STATE_CHECKED);
626	
627	    return row;
628	}
