99	static rtw_result_t safe_scan_handler(rtw_scan_handler_result_t *r) {
100	    if (!r) return RTW_SUCCESS;
101	    if (r->scan_complete) {
102	        g_scan_done = 1; // 仅标记完成
103	        return RTW_SUCCESS;
104	    }
105	    // 数组边界拦截防御
106	    if (g_ap_count >= DM_NET_AP_MAX) return RTW_SUCCESS;
107	    
108	    dm_net_ap_t *ap = &g_aps[g_ap_count];
109	    // 使用 memcpy 防止 SSID 越界溢出
110	    memcpy(ap->ssid, r->ap_details.SSID.val, r->ap_details.SSID.len);
111	    ap->ssid[r->ap_details.SSID.len] = '\0';
112	    ap->security = r->ap_details.security;
113	    ap->rssi = r->ap_details.signal_strength;
114	    g_ap_count++;
115	    return RTW_SUCCESS;
116	}
