/* ================================================================
 * BOOKS — 电子书阅读器（bookdevjianyi.txt 方案 2026-08-08）
 * 书架扫描 /sdcard/book（与音乐 /sdcard/music 同约定），流式分页阅读，
 * 避免大 txt 整本载入 LVGL 造成 OOM。
 * ================================================================ */

#define DM_MAX_BOOKS   32
#define DM_BOOK_DIR    "/sdcard/book"

static char     dm_book_paths[DM_MAX_BOOKS][160];
static char     dm_book_titles[DM_MAX_BOOKS][64];
static uint32_t dm_book_count;

/* 阅读器状态（bookdevjianyi.txt：流式分页，只 fread 一屏） */
static lv_obj_t *book_reader_overlay;   /* 全屏阅读器覆盖层 */
static lv_obj_t *book_reader_text;      /* 正文 label */
static lv_obj_t *book_reader_title_lbl; /* 顶部书名 */
static lv_obj_t *book_reader_prog;      /* 底部进度 */
static int       book_cur_idx;          /* 当前阅读书籍索引 */
static long      book_offset;           /* 文件偏移（分页游标） */
static long      book_file_size;        /* 文件总字节 */
static int       g_eye_care_mode;       /* 护眼模式（1=羊皮纸） */

#define BOOK_PAGE_CHARS 1400   /* 每屏大约读取字节数（UTF-8 边界截断） */

/* 扫描 /sdcard/book 下 .txt 文件，返回数量 */
static uint32_t book_scan_directory(void)
{
    DIR *dir;
    struct dirent *ent;
    uint32_t count = 0;

    dm_book_count = 0;
    dir = opendir(DM_BOOK_DIR);
    if (dir == NULL)
        return 0;

    while ((ent = readdir(dir)) != NULL && count < DM_MAX_BOOKS)
    {
        const char *dot = strrchr(ent->d_name, '.');
        if (dot == NULL || dot == ent->d_name)
            continue;
        if (strcasecmp(dot, ".txt") != 0)
            continue;

        snprintf(dm_book_paths[count], sizeof(dm_book_paths[count]),
                 "%s/%s", DM_BOOK_DIR, ent->d_name);
        snprintf(dm_book_titles[count], sizeof(dm_book_titles[count]),
                 "%.*s", (int)(dot - ent->d_name), ent->d_name);
        count++;
    }

    closedir(dir);
    dm_book_count = count;
    return count;
}

