/* 分页引擎（任务 4）：读取 book_offset 起的 BOOK_PAGE_CHARS 字节，
 * UTF-8 边界安全截断后渲染到正文 label，并更新底部进度百分比。
 * 每次只 fread 一屏——大 txt 不整本载入内存（bookdevjianyi.txt）。 */
static void book_page_render(void)
{
    FILE *f;
    static char buf[BOOK_PAGE_CHARS + 8];
    size_t rd;
    int n;
    int pct;

    if (book_reader_text == NULL)
        return;

    f = fopen(dm_book_paths[book_cur_idx], "rb");
    if (f == NULL) {
        lv_label_set_text(book_reader_text, "（无法打开文件）");
        return;
    }

    fseek(f, book_offset, SEEK_SET);
    rd = fread(buf, 1, BOOK_PAGE_CHARS, f);
    fclose(f);

    if (rd == 0) {
        lv_label_set_text(book_reader_text, "—— 全文完 ——");
        if (book_reader_prog)
            lv_label_set_text(book_reader_prog, "100%");
        return;
    }

    /* UTF-8 边界截断：避免页尾切到半个汉字 */
    n = book_utf8_trim(buf, (int)rd);
    lv_label_set_text(book_reader_text, buf);

    /* 进度 = 当前页起点 / 文件总长 */
    pct = (book_file_size > 0)
        ? (int)(book_offset * 100 / book_file_size) : 0;
    if (book_reader_prog)
        lv_label_set_text_fmt(book_reader_prog, "%d%%", pct);
}

