/* ================================================================
 * BOOK READER — 全屏阅读器（bookdevjianyi.txt 2026-08-08）
 * 顶部沉浸式导航（返回 + 书名）+ 全屏正文区 + 底部胶囊控制台。
 * 分页引擎（book_page_render / UTF-8 截断）在下一节实现。
 * ================================================================ */

/* 护眼模式配色（bookdevjianyi.txt：羊皮纸 vs 正常白）
 * 正常：背景 COL_CARD(白)，文字 COL_TEXT(深)；护眼：背景 #F9F6F0
 * 极浅羊皮纸，文字 #4A3F35 柔和深咖——比纯黑白对比度更低更舒适 */
#define BOOK_BG_NORMAL   0xFFFFFF
#define BOOK_BG_EYE      0xF9F6F0
#define BOOK_TX_NORMAL   COL_TEXT
#define BOOK_TX_EYE      0x4A3F35

/* 根据 g_eye_care_mode 重绘阅读器配色 */
static void book_apply_eye_style(void)
{
    uint32_t bg  = g_eye_care_mode ? BOOK_BG_EYE : BOOK_BG_NORMAL;
    uint32_t tx  = g_eye_care_mode ? BOOK_TX_EYE : BOOK_TX_NORMAL;

    if (book_reader_overlay)
        lv_obj_set_style_bg_color(book_reader_overlay, lv_color_hex(bg), 0);
    if (book_reader_text)
        lv_obj_set_style_text_color(book_reader_text, lv_color_hex(tx), 0);
    if (book_reader_title_lbl)
        lv_obj_set_style_text_color(book_reader_title_lbl, lv_color_hex(tx), 0);
}

/* 护眼模式按钮：切换 g_eye_care_mode 并平滑重绘配色 */
static void book_eye_toggle_cb(lv_event_t *e)
{
    (void)e;
    g_eye_care_mode = g_eye_care_mode ? 0 : 1;
    book_apply_eye_style();
}

