int dm_net_wifi_scan_start(void)
{
    int ret;

    g_ap_count  = 0;
    g_scan_done = 0;

    /* 驱动忙（scan_running 残留 / 连接流程占用）时 wifi_scan_networks
     * 内部等 2s 后返回 RTW_TIMEOUT，此时回调永不触发、scan_done 恒 0。
     * 显式检查返回值，让 UI 能提示"扫描失败"而不是永远"扫描中…"。 */
    ret = wifi_scan_networks(dm_net_scan_handler, NULL);
    if (ret != RTW_SUCCESS) {
        g_scan_fail = 1;
        return -1;
    }
    g_scan_fail = 0;
    return 0;
}

